/// Mirrors `#if defined(FOOT_GRAPHEME_CLUSTERING)` in `struct vt`
/// (terminal.h). Must match the C build's `-DFOOT_GRAPHEME_CLUSTERING`.
pub const grapheme_clustering = build_options.grapheme_clustering;

// The C layout, generated by `scripts/gen_abi_probe.py` and compiled by
// meson (`abi_probe.c` -> `c_layout.zig`). `expectAbi()` below compares every
// mirrored struct/field against these values at compile time, so a mismatch
// between this file and the C headers is a build error, not a runtime bug.
const abi = @import("c_layout");

const vt_size: usize = abi.Vt__size;
const vt_utf8_offset: usize = abi.Vt_utf8;
const terminal_size: usize = abi.Terminal__size;
const terminal_grid_offset: usize = abi.Terminal_grid;
const terminal_render_offset: usize = abi.Terminal_render;
const terminal_selection_offset: usize = abi.Terminal_selection;
const terminal_is_searching_offset: usize = abi.Terminal_is_searching;
const terminal_search_offset: usize = abi.Terminal_search;
const terminal_url_offset: usize = abi.Terminal_url;
const terminal_grapheme_shaping_offset: usize = abi.Terminal_grapheme_shaping;

/// Compile-time comparison of a mirror with the generated C layout.
///
/// `key_prefix` is the name used by `scripts/gen_abi_probe.py` for the type
/// (usually the Zig type name). Every non-`_`-prefixed field must have a
/// corresponding probe entry; otherwise the mirror has grown a field the
/// probe does not know about and the error tells you to regenerate it.
fn expectAbi(comptime T: type, comptime key_prefix: []const u8) void {
    comptime {
        // The wayland mirrors (B1/B2) have hundreds of fields; the default
        // comptime branch quota of 1000 is not enough for the recursion.
        @setEvalBranchQuota(100_000);

        const info = @typeInfo(T);
        const size_key = key_prefix ++ "__size";

        if (!@hasDecl(abi, size_key)) {
            @compileError("abi_probe is missing " ++ size_key ++
                " — run scripts/gen_abi_probe.py");
        }
        if (@sizeOf(T) != @field(abi, size_key)) {
            @compileError(std.fmt.comptimePrint(
                "ABI size mismatch: {s}: C={d} zig={d}",
                .{ size_key, @field(abi, size_key), @sizeOf(T) }));
        }

        // Unions and packed structs (bit-fields) only get a size check.
        if (info != .@"struct") return;
        if (info.@"struct".layout == .@"packed") return;

        for (info.@"struct".fields) |f| {
            // `_pad*`, `_font_state`, `_sixel_flags`, ... are Zig-only.
            if (f.name.len > 0 and f.name[0] == '_') continue;
            // Feature-gated fields are `u0` when the C field does not exist.
            if (@typeInfo(f.type) == .int and @bitSizeOf(f.type) == 0) continue;

            const key = key_prefix ++ "_" ++ f.name;
            if (!@hasDecl(abi, key)) {
                @compileError("abi_probe is missing " ++ key ++
                    " — run scripts/gen_abi_probe.py");
            }
            if (@offsetOf(T, f.name) != @field(abi, key)) {
                @compileError(std.fmt.comptimePrint(
                    "ABI offset mismatch: {s}: C={d} zig={d}",
                    .{ key, @field(abi, key), @offsetOf(T, f.name) }));
            }

            const field_size_key = key ++ "__size";
            if (@hasDecl(abi, field_size_key) and
                @sizeOf(f.type) != @field(abi, field_size_key))
            {
                @compileError(std.fmt.comptimePrint(
                    "ABI field size mismatch: {s}: C={d} zig={d}",
                    .{ field_size_key, @field(abi, field_size_key), @sizeOf(f.type) }));
            }

            // Recurse into value-typed structs the probe also looked inside.
            switch (@typeInfo(f.type)) {
                .@"struct" => |s| {
                    if (s.layout != .@"packed" and
                        @hasDecl(abi, key ++ "__abi_fields"))
                    {
                        expectAbi(f.type, key);
                    }
                },
                else => {},
            }
        }
    }
}

