//
// Config mirror (config.h). Phase 2 step C1: the layout only — the parser is
// still config.c. Having this lets terminal/selection code read `term->conf`
// directly instead of going through terminal_shim_conf_*() accessors.
//

pub const PtOrPx = extern struct {
    px: i16,
    pt: f32,
};

/// Port of terminal.c's term_pt_or_px_as_pixels().
///
/// A pt_or_px value with px == 0 is a point size and is converted using the
/// font DPI (or 96 when the font isn't DPI-sized); otherwise it is a pixel
/// value scaled by the current surface scale. Kept here, next to the type,
/// because it is pure and therefore unit-testable without a terminal.
pub fn ptOrPxAsPixels(term: *const Terminal, pt_or_px: *const PtOrPx) c_int {
    const scale: f32 = if (!term.font_is_sized_by_dpi) term.scale else 1.0;
    const dpi: f32 = if (term.font_is_sized_by_dpi) term.font_dpi else 96.0;

    const pixels: f32 = if (pt_or_px.px == 0)
        pt_or_px.pt * scale * dpi / 72.0
    else
        @as(f32, @floatFromInt(pt_or_px.px)) * scale;

    return @intFromFloat(@round(pixels));
}

/// Port of terminal.c's term_font_baseline().
///
/// With a custom line height the glyph is centred in the cell; otherwise the
/// baseline sits descent pixels above the bottom of the cell. The fcft
/// ascent/descent values come in as arguments so this stays testable.
pub fn fontBaseline(term: *const Terminal, ascent: c_int, descent: c_int) c_int {
    const line_height = term.cell_height;
    const font_height = ascent + descent;

    const glyph_top_y: c_int = if (term.font_line_height.px >= 0)
        @intFromFloat(@round(@as(f64, @floatFromInt(line_height - font_height)) / 2.0))
    else
        0;

    return @as(c_int, term.font_y_ofs) + line_height - glyph_top_y - descent;
}

/// Port of terminal.c's term_line_height_update().
///
/// The configured line height is expressed relative to the *original* font
/// size, so it must be rescaled when the runtime font size changes (font size
/// shortcuts). A negative px means "use the font's own line height".
pub fn lineHeightUpdate(term: *Terminal) void {
    const conf = term.conf.?;

    if (conf.line_height.px < 0) {
        term.font_line_height.pt = 0;
        term.font_line_height.px = -1;
        return;
    }

    const dpi: f32 = if (term.font_is_sized_by_dpi) term.font_dpi else 96.0;

    const original = conf.fonts[0].arr.?[0];
    const font_original_pt_size: f32 = if (original.px_size > 0)
        @as(f32, @floatFromInt(original.px_size)) * 72.0 / dpi
    else
        original.pt_size;

    const current = term.font_sizes[0].?.*;
    const font_current_pt_size: f32 = if (current.px_size > 0)
        @as(f32, @floatFromInt(current.px_size)) * 72.0 / dpi
    else
        current.pt_size;

    const change = font_current_pt_size / font_original_pt_size;
    const line_original_pt_size: f32 = if (conf.line_height.px > 0)
        @as(f32, @floatFromInt(conf.line_height.px)) * 72.0 / dpi
    else
        conf.line_height.pt;

    term.font_line_height.px = 0;
    term.font_line_height.pt = @max(line_original_pt_size * change, 0.0);
}

