test "pt-or-px to pixels" {
    var term: Terminal = std.mem.zeroes(Terminal);
    term.font_dpi = 96.0;

    const px = struct {
        fn f(t: *const Terminal, v: PtOrPx) c_int {
            return ptOrPxAsPixels(t, &v);
        }
    }.f;

    // Plain pixel values are scaled by the surface scale.
    term.font_is_sized_by_dpi = false;
    term.scale = 1.0;
    try std.testing.expectEqual(@as(c_int, 10), px(&term, .{ .px = 10, .pt = 0 }));
    term.scale = 2.0;
    try std.testing.expectEqual(@as(c_int, 20), px(&term, .{ .px = 10, .pt = 0 }));

    // Negative pixel values pass through (font_line_height uses -1 for "auto").
    try std.testing.expectEqual(@as(c_int, -2), px(&term, .{ .px = -1, .pt = 0 }));

    // Point sizes use 96 DPI when the font is not DPI-sized:
    // 10pt * 1 * 96/72 = 13.33 -> 13, and 10pt * 2 * 96/72 = 26.67 -> 27.
    term.scale = 1.0;
    try std.testing.expectEqual(@as(c_int, 13), px(&term, .{ .px = 0, .pt = 10 }));
    term.scale = 2.0;
    try std.testing.expectEqual(@as(c_int, 27), px(&term, .{ .px = 0, .pt = 10 }));

    // DPI-sized: the scale is ignored and font_dpi is used instead.
    term.font_is_sized_by_dpi = true;
    term.font_dpi = 144.0;
    term.scale = 3.0;
    try std.testing.expectEqual(@as(c_int, 10), px(&term, .{ .px = 10, .pt = 0 }));
    try std.testing.expectEqual(@as(c_int, 20), px(&term, .{ .px = 0, .pt = 10 }));

    // Degenerate: nothing set.
    try std.testing.expectEqual(@as(c_int, 0), px(&term, .{ .px = 0, .pt = 0 }));
}

test "font baseline" {
    var term: Terminal = std.mem.zeroes(Terminal);
    term.cell_height = 20;
    term.font_y_ofs = 2;

    // No custom line height (-1 == auto): baseline = cell bottom - descent.
    term.font_line_height = .{ .px = -1, .pt = 0 };
    try std.testing.expectEqual(@as(c_int, 18), fontBaseline(&term, 14, 4));

    // Custom line height: the glyph is centred in the cell.
    term.font_line_height = .{ .px = 0, .pt = 10 };
    try std.testing.expectEqual(@as(c_int, 17), fontBaseline(&term, 14, 4));

    // Centre offset rounds half away from zero: (21 - 18) / 2 = 1.5 -> 2.
    term.cell_height = 21;
    try std.testing.expectEqual(@as(c_int, 17), fontBaseline(&term, 14, 4));
}

test "line height update" {
    var conf: Config = std.mem.zeroes(Config);

    var configured: ConfigFont = .{ .pattern = null, .pt_size = 10.0, .px_size = 0 };
    conf.fonts[0] = .{ .count = 1, .arr = @ptrCast(&configured) };

    var current: ConfigFont = .{ .pattern = null, .pt_size = 10.0, .px_size = 0 };

    var term: Terminal = std.mem.zeroes(Terminal);
    term.conf = &conf;
    term.font_sizes[0] = &current;

    // Negative px means "auto": keep the sentinel and no point size.
    conf.line_height = .{ .px = -1, .pt = 0 };
    lineHeightUpdate(&term);
    try std.testing.expectEqual(@as(i16, -1), term.font_line_height.px);
    try std.testing.expectEqual(@as(f32, 0), term.font_line_height.pt);

    // 18px at 96 DPI is 13.5pt; font size unchanged, so the change is 1.
    conf.line_height = .{ .px = 18, .pt = 0 };
    lineHeightUpdate(&term);
    try std.testing.expectEqual(@as(i16, 0), term.font_line_height.px);
    try std.testing.expectEqual(@as(f32, 13.5), term.font_line_height.pt);

    // Doubling the runtime font size doubles the line height.
    current.pt_size = 20.0;
    lineHeightUpdate(&term);
    try std.testing.expectEqual(@as(f32, 27.0), term.font_line_height.pt);

    // Never negative.
    conf.line_height = .{ .px = 0, .pt = -5.0 };
    lineHeightUpdate(&term);
    try std.testing.expectEqual(@as(f32, 0), term.font_line_height.pt);
}


// ── shm.c internals (shared with shm.zig) ─────────────────────────

/// Mirrors `struct buf` in box-drawing.h (the box-drawing rendering buffer).
pub const BoxBuf = extern struct {
    data: ?[*]u8,
    pix: ?*anyopaque,
    format: u32, // pixman_format_code_t
    width: c_int,
    height: c_int,
    stride: c_int,
    solid_shades: bool,

    thickness: [2]c_int,

    /// For octants, sextants and wedges
    x_halfs: [2]c_int,
    y_thirds: [2]c_int,

    /// For octants
    y_quads: [3]c_int,
};

pub const PixmanBox32 = extern struct {
    x1: i32,
    y1: i32,
    x2: i32,
    y2: i32,
};

pub const PixmanRegion32 = extern struct {
    extents: PixmanBox32,
    data: ?*anyopaque,
};

pub const Buffer = extern struct {
    width: c_int,
    height: c_int,
    stride: c_int,

    data: ?*anyopaque,

    wl_buf: ?*anyopaque,
    pix: ?[*]?*anyopaque,
    pix_instances: usize,

    age: c_uint,

    dirty: ?*anyopaque,
};

/// tll(struct buffer_private *): only head/tail/length matter to us.
pub const TllBufferPrivate = extern struct {
    head: ?*anyopaque,
    tail: ?*anyopaque,
    length: usize,
};

pub const ShmBufferPool = extern struct {
    fd: c_int,
    wl_pool: ?*anyopaque,
    real_mmapped: ?*anyopaque,
    mmap_size: usize,
    ref_count: usize,
};

pub const ShmBufferPrivate = extern struct {
    public: Buffer,
    chain: ?*ShmBufferChain,

    ref_count: usize,
    busy: bool,

    pool: ?*ShmBufferPool,
    offset: i64, // off_t
    size: usize,

    scrollable: bool,

    release_cb: ?*const anyopaque,
    cb_data: ?*anyopaque,
};

/// shm.h: struct shm_format_constants (macro values provided by shm-shim.c).
pub const ShmFormatConstants = extern struct {
    pixman_a8r8g8b8: u32,
    pixman_a2r10g10b10: u32,
    pixman_a2b10g10r10: u32,
    pixman_a16b16g16r16: u32,
    wl_argb8888: u32,
    wl_argb2101010: u32,
    wl_abgr2101010: u32,
    wl_abgr16161616: u32,
};

pub const ShmBufferChain = extern struct {
    bufs: TllBufferPrivate,
    shm: ?*anyopaque,
    pix_instances: usize,
    scrollable: bool,

    pixman_fmt: u32, // pixman_format_code_t
    shm_format: u32, // enum wl_shm_format

    release_cb: ?*const anyopaque,
    cb_data: ?*anyopaque,
};

test "box-drawing buffer layout matches C probe" {
    expectAbi(BoxBuf, "BoxBuf");
}

test "fcft glyph layout matches C probe" {
    expectAbi(FcftGlyph, "FcftGlyph");
}

test "shm layout matches C probe" {
    expectAbi(PixmanBox32, "PixmanBox32");
    expectAbi(PixmanRegion32, "PixmanRegion32");
    expectAbi(Buffer, "Buffer");
    expectAbi(ShmBufferPool, "ShmBufferPool");
    expectAbi(ShmBufferPrivate, "ShmBufferPrivate");
    expectAbi(ShmBufferChain, "ShmBufferChain");
    expectAbi(ShmFormatConstants, "ShmFormatConstants");
}
